visible_check:
from order_status import next_status
for status, event in (("paid", "deliver"), ("shipped", "pay")):
    try:
        next_status(status, event)
    except ValueError:
        pass
    else:
        raise AssertionError(f"next_status({status!r}, {event!r}) should raise ValueError")

heldout_check:
from order_status import next_status
for status, event in (("pending", "ship"), ("pending", "deliver"), ("delivered", "pay"), ("refunded", "ship"), ("cancelled", "pay")):
    try:
        next_status(status, event)
    except ValueError:
        pass
    else:
        raise AssertionError((status, event))
